#!/bin/sh
# generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
#
# Общий помощник shell-скриптов .claude/bin/: корень workspace и параметры
# .claude/workspace.json. Подключается скриптом, который перед этим задал self_dir —
# каталог, где лежит он сам:
#
#     self_dir=$(cd -- "$(dirname -- "$0")" && pwd)
#     . "$self_dir/lib/workspace.sh"
#     ws_load || exit 1     # разбор один раз на весь скрипт
#     ws_root               # корень workspace: WORKSPACE_ROOT или каталог над .claude/
#     ws_get ui             # значение ключа с дефолтом; массив — по строке на элемент
#     ws_repos              # строки «<имя>\t<путь от корня>» по правилу обхода
#
# Разбор JSON, дефолты и обход репозиториев живут в lib/workspace.mjs, здесь только
# транспорт. ws_load нужен в основной оболочке скрипта: `$(ws_get …)` исполняется
# в подоболочке, и кеш, заведённый там, до следующего вызова не доживает — без ws_load
# каждый ws_get заново зовёт node.

_ws_find_root() {
    if [ -n "${WORKSPACE_ROOT:-}" ]; then
        (cd -- "$WORKSPACE_ROOT" 2>/dev/null && pwd) && return 0
        printf 'WORKSPACE_ROOT — не каталог: %s\n' "$WORKSPACE_ROOT" >&2
        return 1
    fi
    _ws_d=${self_dir:?workspace.sh: self_dir не задан — задай его до подключения}
    while :; do
        if [ "${_ws_d##*/}" = ".claude" ]; then
            _ws_up=${_ws_d%/*}
            printf '%s\n' "${_ws_up:-/}"
            return 0
        fi
        _ws_next=${_ws_d%/*}
        [ -n "$_ws_next" ] && [ "$_ws_next" != "$_ws_d" ] || break
        _ws_d=$_ws_next
    done
    printf 'не найден каталог .claude/ над %s — задай WORKSPACE_ROOT\n' "$self_dir" >&2
    return 1
}

ws_load() {
    command -v node >/dev/null 2>&1 || { echo "нужен node: параметры .claude/workspace.json читает он" >&2; return 1; }
    _ws_root=$(_ws_find_root) || return 1
    _ws_dump=$(node "${self_dir:?}/lib/workspace.mjs" dump "$_ws_root") || return 1
    _ws_loaded=1
}

ws_root() {
    [ -n "${_ws_loaded:-}" ] || ws_load || return 1
    printf '%s\n' "$_ws_root"
}

ws_get() {
    [ -n "${_ws_loaded:-}" ] || ws_load || return 1
    printf '%s\n' "$_ws_dump" | awk -F '\t' -v key="$1" '
        $1 == "K" && $2 == key { known = 1 }
        ($1 == "k" || $1 == "a") && $2 == key { sub(/^[^\t]*\t[^\t]*\t/, ""); print }
        END { if (!known) { print "workspace.json: неизвестный ключ " key > "/dev/stderr"; exit 1 } }'
}

ws_repos() {
    [ -n "${_ws_loaded:-}" ] || ws_load || return 1
    printf '%s\n' "$_ws_dump" | awk -F '\t' '$1 == "r" { print $2 "\t" $3 }'
}
